11	/**
12	 * One heading and the section that starts at it.
13	 *
14	 * Positions use ProseMirror's coordinate system. `from` is the position before
15	 * the heading node, `contentFrom` is the first selectable position inside it,
16	 * and `to` is the first position after the complete section, including all
17	 * subordinate headings. Those ranges are deliberately part of the Wave 1
18	 * contract so section reordering can move `[from, to)` in one transaction.
19	 */
20	export interface DocumentOutlineHeading {
21	  id: string;
22	  text: string;
23	  label: string;
24	  level: number;
25	  depth: number;
26	  index: number;
27	  from: number;
28	  contentFrom: number;
29	  to: number;
30	  children: DocumentOutlineHeading[];
31	}
