394| /**
395|  * Resolve the effective numeric page margins (in rem) for a layout.
396|  *
397|  * Three generations of the setting have to keep rendering: the coarse
398|  * `margin` preset, the symmetric `marginX`, and the independent left/right
399|  * the ruler writes. Each falls back to the one before it, so an old document
400|  * opens with the page its writer chose rather than the current default.
401|  */
402| export function resolveMargins(layout: LayoutSettings): ResolvedMargins {
403|   const presetX = MARGIN_PRESET_REM[layout.margin] ?? MARGIN_PRESET_REM.normal;
404|   const x = layout.marginX ?? presetX;
405|   return {
406|     left: layout.marginLeft ?? x,
407|     right: layout.marginRight ?? x,
408|     top: layout.marginTop ?? (layout.margin === "roomy" ? 5 : 2.5),
409|     bottom: layout.marginBottom ?? (layout.margin === "roomy" ? 5 : 4),
410|   };
411| }
